// MediCare unified Codespaces server
// Current Diagnosis page redesigned to match the supplied Payments UI/UX.
// Run: npm start
// Default port: 3000

const http = require('http');
const fs = require('fs');
const path = require('path');
const url = require('url');

const PORT = Number(process.env.PORT || 3000);
const HOST = process.env.HOST || '0.0.0.0';
const ROOT = __dirname;

const DIAGNOSIS_HTML = Buffer.from(
  '',
  'base64'
).toString('utf8');

function send(res, status, contentType, body, cache = 'no-store') {
  res.writeHead(status, {
    'Content-Type': contentType,
    'Cache-Control': cache,
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'no-referrer'
  });
  res.end(body);
}

function serveFile(res, fileName, contentType) {
  const filePath = path.join(ROOT, fileName);
  fs.readFile(filePath, (err, data) => {
    if (err) {
      send(res, 404, 'text/plain; charset=utf-8', `Missing file: ${fileName}`);
      return;
    }
    send(res, 200, contentType, data);
  });
}

const server = http.createServer((req, res) => {
  const pathname = url.parse(req.url).pathname;

  if (pathname === '/health') {
    send(
      res,
      200,
      'application/json; charset=utf-8',
      JSON.stringify({
        status: 'ok',
        service: 'medicare-patient-portal',
        pages: ['current-diagnosis', 'payments']
      })
    );
    return;
  }

  // Restyled Current Diagnosis / Medical History page.
  if (pathname === '/' || pathname === '/diagnosis' || pathname === '/current-diagnosis') {
    send(res, 200, 'text/html; charset=utf-8', DIAGNOSIS_HTML);
    return;
  }

  // Existing first-three-file Payments UI.
  if (pathname === '/payments' || pathname === '/indexf.html') {
    serveFile(res, 'indexf.html', 'text/html; charset=utf-8');
    return;
  }

  if (pathname === '/styles.css') {
    serveFile(res, 'styles.css', 'text/css; charset=utf-8');
    return;
  }

  if (pathname === '/app.js') {
    serveFile(res, 'app.js', 'application/javascript; charset=utf-8');
    return;
  }

  send(res, 404, 'text/plain; charset=utf-8', '404 - Not Found');
});

server.listen(PORT, HOST, () => {
  console.log(`MediCare patient portal running on http://${HOST}:${PORT}`);
  console.log('Current diagnosis: /');
  console.log('Payments: /payments');
  console.log('Health check: /health');
  console.log('In GitHub Codespaces, open port 3000 from the Ports tab.');
});

process.on('SIGTERM', () => server.close(() => process.exit(0)));
process.on('SIGINT', () => server.close(() => process.exit(0)));
